const languages: Language[] = ["it", "en", "es", "fr", "de"];

export function cockpitLabelKey(text: string): string {
  return textKeys[text] ?? text;
}

export function cockpitDictionary(language: Language): Record<string, string> {
  const index = Math.max(0, languages.indexOf(language));
  return Object.fromEntries(Object.entries(entries).map(([key, values]) => [key, values[index] ?? values[0]]));
}
